package com.infinitylibrary.community;

import com.infinitylibrary.InfinityLibraryPlugin;
import com.infinitylibrary.gui.LibraryMenu;
import org.bukkit.*;
import org.bukkit.entity.Player;
import org.bukkit.configuration.file.YamlConfiguration;
import io.papermc.paper.registry.data.dialog.input.*;
import net.kyori.adventure.text.Component;
import java.nio.file.Path;
import java.util.*;

public final class NoticeboardManager {
    public record Notice(UUID id,UUID author,String authorName,String title,String text,long created,long expires,boolean pinned){public Notice{AtomicYaml.text(title,48,"Title");AtomicYaml.text(text,2000,"Notice");if(title.isBlank()||text.isBlank()||expires<=created)throw new IllegalArgumentException("A notice needs a title, text and valid expiry.");}public boolean active(long now){return expires>now;}}
    private final InfinityLibraryPlugin plugin;private final Path file;private final Map<UUID,Notice> posts=new LinkedHashMap<>();private final Map<UUID,Long> lastPosted=new HashMap<>();private final Set<String> boards=new HashSet<>();
    public NoticeboardManager(InfinityLibraryPlugin p){plugin=p;file=p.getDataFolder().toPath().resolve("noticeboard.yml");load();}
    public void load(){
        var y=AtomicYaml.read(file);Map<UUID,Long> times=new HashMap<>();Map<UUID,Notice> loaded=new LinkedHashMap<>();Set<String> locations=new HashSet<>(y.getStringList("boards"));var cooldowns=y.getConfigurationSection("last-posted");if(cooldowns!=null)for(String id:cooldowns.getKeys(false))times.put(UUID.fromString(id),cooldowns.getLong(id));var root=y.getConfigurationSection("notices");
        if(root!=null)for(String id:root.getKeys(false)){var s=root.getConfigurationSection(id);var n=new Notice(UUID.fromString(id),UUID.fromString(s.getString("author")),s.getString("author-name"),s.getString("title"),s.getString("text"),s.getLong("created"),s.getLong("expires"),s.getBoolean("pinned"));loaded.put(n.id(),n);}
        posts.clear();posts.putAll(loaded);lastPosted.clear();lastPosted.putAll(times);boards.clear();boards.addAll(locations);
    }
    public void save(){YamlConfiguration y=new YamlConfiguration();y.set("boards",new ArrayList<>(boards));lastPosted.forEach((id,time)->y.set("last-posted."+id,time));for(var n:posts.values()){var s=y.createSection("notices."+n.id());s.set("author",n.author().toString());s.set("author-name",n.authorName());s.set("title",n.title());s.set("text",n.text());s.set("created",n.created());s.set("expires",n.expires());s.set("pinned",n.pinned());}AtomicYaml.write(file,y);}
    public List<Notice> active(){long now=System.currentTimeMillis();return posts.values().stream().filter(n->n.active(now)).sorted(Comparator.comparing(Notice::pinned).reversed().thenComparing(Comparator.comparingLong(Notice::created).reversed())).toList();}
    public Notice post(Player p,String title,String text,int days){if(!p.hasPermission("infinitylibrary.notice.post"))throw new IllegalArgumentException("Missing permission infinitylibrary.notice.post");long now=System.currentTimeMillis();int max=Math.max(1,Math.min(90,plugin.getConfig().getInt("community.notice-max-days",30)));if(days<1||days>max)throw new IllegalArgumentException("Expiry must be 1–"+max+" days.");if(!p.hasPermission("infinitylibrary.admin")){if(active().stream().filter(n->n.author().equals(p.getUniqueId())).count()>=5)throw new IllegalArgumentException("You already have five active notices.");if(now-lastPosted.getOrDefault(p.getUniqueId(),0L)<60000)throw new IllegalArgumentException("Wait one minute between notices.");}if(active().size()>=Math.max(10,plugin.getConfig().getInt("community.notice-limit",200)))throw new IllegalArgumentException("The noticeboard is full.");Notice n=new Notice(UUID.randomUUID(),p.getUniqueId(),p.getName(),title,text,now,now+days*86400000L,false);Map<UUID,Notice> old=new LinkedHashMap<>(posts);posts.values().removeIf(x->!x.active(now)&&now-x.expires()>86400000L);posts.put(n.id(),n);Long previousPost=lastPosted.put(p.getUniqueId(),now);try{save();}catch(RuntimeException ex){posts.clear();posts.putAll(old);if(previousPost==null)lastPosted.remove(p.getUniqueId());else lastPosted.put(p.getUniqueId(),previousPost);throw ex;}return n;}
    public void remove(Player p,UUID id){Notice old=posts.get(id);if(old==null)throw new IllegalArgumentException("Notice not found.");if(!old.author().equals(p.getUniqueId())&&!p.hasPermission("infinitylibrary.admin"))throw new IllegalArgumentException("Only the author or an administrator may remove this notice.");posts.remove(id);try{save();}catch(RuntimeException ex){posts.put(id,old);throw ex;}}
    public void pin(Player p,UUID id,boolean value){if(!p.hasPermission("infinitylibrary.admin"))throw new IllegalArgumentException("Only administrators can pin notices.");Notice old=posts.get(id);if(old==null)throw new IllegalArgumentException("Notice not found.");posts.put(id,new Notice(old.id(),old.author(),old.authorName(),old.title(),old.text(),old.created(),old.expires(),value));try{save();}catch(RuntimeException ex){posts.put(id,old);throw ex;}}
    private String boardKey(Location l){return l.getWorld().getName()+"|"+l.getBlockX()+"|"+l.getBlockY()+"|"+l.getBlockZ();}
    public boolean isBoard(org.bukkit.block.Block block){return block!=null&&boards.contains(boardKey(block.getLocation()));}
    public void bind(Player p,Location at,boolean enabled){if(!p.hasPermission("infinitylibrary.admin"))throw new IllegalArgumentException("Only administrators can bind a noticeboard block.");String key=boardKey(at);if(enabled&&!boards.contains(key)&&boards.size()>=64)throw new IllegalArgumentException("Maximum 64 physical noticeboards.");boolean was=boards.contains(key);if(enabled)boards.add(key);else boards.remove(key);try{save();}catch(RuntimeException ex){if(was)boards.add(key);else boards.remove(key);throw ex;}}
    public void browser(Player p,int page){List<String> entries=new ArrayList<>();active().forEach(n->entries.add("notice:"+n.id()));plugin.getBookStorageManager().allBooks().stream().filter(b->b.isPublic()).sorted(Comparator.comparing(com.infinitylibrary.storage.BookStorageManager.StoredBook::insertedAt).reversed()).limit(10).forEach(b->entries.add("book:"+b.id()));page=Math.max(0,Math.min(page,Math.max(0,(entries.size()-1)/45)));LibraryMenu m=new LibraryMenu(p,LibraryMenu.Screen.NOTICEBOARD,54,"Library • Community noticeboard");m.entry(53,Integer.toString(page));var w=plugin.getBookWritingManager();for(int i=0;i<45&&page*45+i<entries.size();i++){String key=entries.get(page*45+i);m.entry(i,key);if(key.startsWith("notice:")){var n=posts.get(UUID.fromString(key.substring(7)));w.icon(m.getInventory(),i,n.pinned()?Material.GLOW_ITEM_FRAME:Material.PAPER,(n.pinned()?"§e★ ":"§f")+n.title(),"§7By "+n.authorName(),"§7Expires: "+java.time.Instant.ofEpochMilli(n.expires()).toString().substring(0,10),"§eClick to read");}else{var b=plugin.getBookStorageManager().allBooks().stream().filter(x->x.id().toString().equals(key.substring(5))).findFirst().orElseThrow();w.icon(m.getInventory(),i,Material.WRITTEN_BOOK,"§bNew book: "+b.title(),"§7By "+b.author(),"§eRead this public book");}}w.icon(m.getInventory(),45,Material.ARROW,"Previous");w.icon(m.getInventory(),47,Material.FEATHER,"Post a notice");w.icon(m.getInventory(),49,Material.CHEST,"Main menu");w.icon(m.getInventory(),51,Material.ARROW,"Next");p.openInventory(m.getInventory());}
    public void compose(Player p){if(!p.hasPermission("infinitylibrary.notice.post"))throw new IllegalArgumentException("Missing permission infinitylibrary.notice.post");plugin.getManagedDialogs().form(p,"Post to the noticeboard",List.of(DialogInput.text("title",Component.text("Title")).maxLength(48).width(300).build(),DialogInput.text("text",Component.text("Announcement, event or recommendation")).maxLength(2000).width(300).multiline(TextDialogInput.MultilineOptions.create(64,160)).build(),DialogInput.text("days",Component.text("Days until expiry")).maxLength(2).initial("7").build()),r->{post(p,r.getText("title"),r.getText("text"),Integer.parseInt(r.getText("days")));browser(p,0);},()->browser(p,0));}
    public void detail(Player p,UUID id){var n=posts.get(id);if(n==null||!n.active(System.currentTimeMillis()))throw new IllegalArgumentException("This notice has expired or was removed.");List<ManagedDialogs.Button> buttons=new ArrayList<>();buttons.add(new ManagedDialogs.Button("Back",r->browser(p,0)));if(n.author().equals(p.getUniqueId())||p.hasPermission("infinitylibrary.admin"))buttons.add(new ManagedDialogs.Button("Remove notice",r->{remove(p,id);browser(p,0);}));if(p.hasPermission("infinitylibrary.admin"))buttons.add(new ManagedDialogs.Button(n.pinned()?"Unpin":"Pin",r->{pin(p,id,!n.pinned());detail(p,id);}));plugin.getManagedDialogs().show(p,n.title(),"By "+n.authorName()+"\n\n"+n.text(),List.of(),buttons);}
    public void handle(Player p,LibraryMenu m,int slot){int page=Integer.parseInt(m.entry(53));if(slot<45&&m.entry(slot)!=null){String key=m.entry(slot);if(key.startsWith("notice:"))detail(p,UUID.fromString(key.substring(7)));else plugin.getReadingManager().open(p,UUID.fromString(key.substring(5)));}else if(slot==45)browser(p,page-1);else if(slot==51)browser(p,page+1);else if(slot==47)compose(p);else if(slot==49)plugin.getGuiManager().openMainMenu(p);}
}
